<?php declare(strict_types=1);final class TaskStepRepository{public function __construct(private mysqli$db){}public function listOwned(int$task,int$u):array{$s=$this->db->prepare('SELECT s.* FROM TaskSteps s JOIN Tasks t ON t.id_=s.task_id_ WHERE s.task_id_=? AND t.user_id_=? ORDER BY s.position');if(!$s)throw new RuntimeException('database_error');$s->bind_param('ii',$task,$u);$s->execute();$o=[];$r=$s->get_result();while($x=$r->fetch_assoc())$o[]=$x;$s->close();return$o;}}
